import { createMemo, createSignal, For, onMount, type Component, type ParentComponent } from "solid-js";
import { render } from "solid-js/web";

import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import {
	DragAndDrop,
	DragDropPredicateT,
	DragEndStatus,
	Draggable,
	Dropzone,
	useDragAndDropContext,
	useDraggableContext,
	type DragEndCallbackT,
} from "#core/ui-next/components/drag-and-drop.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { SandboxBox } from "#core/ui-next/sandbox/sandbox-box.jsx";
import { SandboxNavigation } from "#core/ui-next/sandbox/sandbox-navigation.js";
import { useAudio, type AudioRule } from "#core/ui-next/services/audio-support.js";

export interface ComponentBoxProps {
	name: string;
}

const ComponentBox: ParentComponent<ComponentBoxProps> = (props) => {
	return (
		<SandboxBox class="flex flex-col justify-start items-center flex-auto">
			<Header class="mb-2">{props.name}</Header>
			{props.children}
		</SandboxBox>
	);
};

const DraggableResource: Component<{ resourceType: string }> = (props) => {
	const draggable = useDraggableContext();
	const dndContext = useDragAndDropContext();

	const filter = createMemo(() => {
		if (draggable.isDragging()) {
			if (!draggable.isRenderingOverlay) {
				return "grayscale(100%)";
			} else if (dndContext.overDropzone()?.canDrop() === true) {
				return "fxs-color-tint(rgb(0, 255, 0))";
			} else if (dndContext.overDropzone()?.canDrop() === false) {
				return "fxs-color-tint(rgb(255, 0, 0))";
			}
		}
		return "";
	});

	return (
		<div
			style={{
				filter: filter(),
				opacity: !draggable.isDragging() || draggable.isRenderingOverlay ? "" : "0.4",
			}}
		>
			<Icon
				class="size-20"
				name={props.resourceType}
			/>
		</div>
	);
};

const DragAndDropExample: Component = () => {
	const audio = useAudio("DraggableResource");

	const handleDragEnd: DragEndCallbackT<string> = (draggable, status, _dropzone) => {
		switch (status) {
			case DragEndStatus.AcceptedByDropzone:
				audio("dropAccept", { resourceType: draggable.data });
				break;
			case DragEndStatus.RejectedByDropzone:
				audio("dropReject");
				break;
		}
	};

	const neverCanDrop: DragDropPredicateT<string, null> = (_draggable, _dropzone) => {
		return () => false;
	};

	const resources = ["RESOURCE_SUGAR", "RESOURCE_COFFEE", "RESOURCE_FISH"];

	return (
		<DragAndDrop onDragEnd={handleDragEnd}>
			<div class="flex flex-row w-full">
				<div class="flex grow">
					<SandboxBox class="flex flex-col justify-start items-center flex-auto">
						<Header class="mb-2">Draggables</Header>
						<div class="flex justify-between">
							<For each={resources}>
								{(resource) => (
									<Draggable
										data={resource}
										onDragEnd={handleDragEnd}
									>
										<DraggableResource resourceType={resource} />
									</Draggable>
								)}
							</For>
						</div>
					</SandboxBox>
				</div>
				<div class="flex size-50">
					<Dropzone data={null}>
						<SandboxBox class="flex flex-col justify-start items-center flex-auto">
							<Header class="mb-2">Dropzone 1</Header>
						</SandboxBox>
					</Dropzone>
				</div>
				<div class="flex size-50">
					<Dropzone
						data={null}
						canDrop={neverCanDrop}
					>
						<SandboxBox class="flex flex-col justify-start items-center flex-auto">
							<Header class="mb-2">Dropzone 2</Header>
						</SandboxBox>
					</Dropzone>
				</div>
			</div>
		</DragAndDrop>
	);
};

const App: Component = () => {
	const simpleNav = new SandboxNavigation();
	let ref: HTMLDivElement | undefined;

	const [leader, setLeader] = createSignal("LEADER_ADA_LOVELACE");

	onMount(() => {
		simpleNav.setFocus(ref!);
	});

	const rules: AudioRule[] = [
		{
			path: "Button",
			events: { activate: "play-button" },
		},
		{
			path: "Contextual/Button",
			events: { activate: "play-button-contextual" },
		},
		{
			path: "Button",
			constraints: {
				leader: "LEADER_ADA_LOVELACE",
			},
			events: { activate: "play-button-{leader}" },
		},
		{
			path: "Button",
			constraints: {
				leader: {
					op: "eq",
					value: "LEADER_GILGAMESH",
				},
			},
			events: { activate: "play-button-gilgamesh" },
		},
		{
			path: "DragonDrop/DraggableResource",
			events: {
				dropAccept: "play-drop-THIS-IS-A-BUG!", //! FIX ME - This event should not have been hit since there's a latter rule that handles dropAccept.
				dropReject: "play-drop-reject",
			},
		},
		{
			path: "DragonDrop/DraggableResource",
			events: {
				dropAccept: "play-drop-{resourceType}",
			},
		},
	];

	return (
		<Panel
			id="sandbox-panel"
			name="Sandbox"
			class="w-full h-full flex flex-col"
			ref={ref}
		>
			<AudioContextProvider rules={rules}>
				<Header class="text-2xl mt-4">UI-Next Audio Sandbox</Header>
				<div class="flex flex-col">
					<ComponentBox name="Simple">
						<Button>Play</Button>
					</ComponentBox>
					<ComponentBox name="Contextual">
						<AudioContextProvider segment="Contextual">
							<div class="flex flex-row">
								<Button>Play</Button>
							</div>
						</AudioContextProvider>
					</ComponentBox>
					<ComponentBox name="Variables">
						<div class="flex flex-row items-center">
							<div class="flex flex-col justify-center items-end mr-4">
								<div class="flex flex-row items-center mb-4">
									Ada Lovelace:&nbsp;
									<RadioButton
										isChecked={leader() == "LEADER_ADA_LOVELACE"}
										onActivate={() => {
											setLeader("LEADER_ADA_LOVELACE");
										}}
									/>
								</div>

								<div class="flex flex-row items-center">
									Gilgamesh:&nbsp;
									<RadioButton
										isChecked={leader() == "LEADER_GILGAMESH"}
										onActivate={() => {
											setLeader("LEADER_GILGAMESH");
										}}
									/>
								</div>
							</div>
							<AudioContextProvider vars={{ leader: leader() }}>
								<Button>Play</Button>
							</AudioContextProvider>
						</div>
					</ComponentBox>
					<ComponentBox name="Drag & Drop">
						<AudioContextProvider segment="DragonDrop">
							<DragAndDropExample />
						</AudioContextProvider>
					</ComponentBox>
				</div>
			</AudioContextProvider>
		</Panel>
	);
};

engine.whenReady.then(() => {
	render(() => {
		return <App />;
	}, document.getElementById("root")!);
});
